void backtrack(int[] nums, int start, List<Integer> path, List<List<Integer>> res) {
    res.add(new ArrayList<>(path));      // record a snapshot
    for (int i = start; i < nums.length; i++) {
        path.add(nums[i]);               // choose
        backtrack(nums, i + 1, path, res); // explore (i+1: no reuse)
        path.remove(path.size() - 1);    // un-choose
    }
}

def permutations(nums):
    res, path, used = [], [], [False] * len(nums)
    def backtrack():
        if len(path) == len(nums):
            res.append(path[:])          # snapshot
            return
        for i in range(len(nums)):
            if used[i]:
                continue
            used[i] = True; path.append(nums[i])    # choose
            backtrack()                              # explore
            path.pop(); used[i] = False              # un-choose
    backtrack()
    return res

def subsets_with_dup(nums):
    nums.sort()                       # group equal values
    res, path = [], []
    def backtrack(start):
        res.append(path[:])
        for i in range(start, len(nums)):
            if i > start and nums[i] == nums[i-1]:
                continue              # skip duplicate at this level
            path.append(nums[i])
            backtrack(i + 1)
            path.pop()
    backtrack(0)
    return res
